from __future__ import absolute_import
from taf.selenium.sbts.pages import rnd_mode


class RndMode(rnd_mode.RndMode):
    def __init__(self, driver, download_checker):
        super(RndMode, self).__init__(driver, download_checker)
        self._feature_flags = FeatureFlagsPage(driver)


class FeatureFlagsPage(rnd_mode.FeatureFlagsPage):

    def __init__(self, driver):
        super(FeatureFlagsPage, self).__init__(driver)
        self._view_panel = FeatureFlagsPageViewPanel(driver)

    def enable_feature_flag(self, feature_name):
        self._view_panel.enable_feature_flag(feature_name)


class FeatureFlagsPageViewPanel(rnd_mode.FeatureFlagsPageViewPanel):

    _FEATURE_ENABLE_SAVE_BUTTON_XPATH = '//p-button[.//span[text()="Save"]]'

    def enable_feature_flag(self, feature_name):
        self.click_element_by_xpath(self._SELECT_CHECKBOX_XPATH.format(feature_name))
        self.click_element_by_xpath(self._FEATURE_ENABLE_SAVE_BUTTON_XPATH)
